using System;
using System.Collections.Generic;

// A curated starting guide, not an exhaustive map or drop database.
// Quest locations: https://classic.battle.net/diablo2exp/quests/
// Region connections and waypoints: https://classic.battle.net/diablo2exp/maps/
public sealed class GuideRegion {
 public int Act;
 public string Name, Points, Quests, Farming;
 public string UpdatedDetails;
 public GuideRegion(int act,string name,string points,string quests,string farming){Act=act;Name=name;Points=points;Quests=quests;Farming=farming;}
 public override string ToString(){return Name;}
 public string Details(){if(!String.IsNullOrEmpty(UpdatedDetails))return UpdatedDetails;return Name.ToUpperInvariant()+"\r\n\r\nPOINTS OF INTEREST\r\n"+Points+"\r\n\r\nQUESTS\r\n"+Quests+"\r\n\r\nFARMING TIPS\r\n"+Farming+GuideDetails.For(Name)+"\r\n\r\nMaps vary between games; rewards and drops depend on difficulty and game mode.\r\n\r\nSources: classic.battle.net/diablo2exp/quests/ and /maps/; Blizzard D2R patch 2.4 notes.";}
}
public static class GuideBook {
 public static readonly GuideRegion[] Regions={
  new GuideRegion(1,"Blood Moor & Den of Evil","Find the Den entrance in the Blood Moor outside the Rogue Encampment.","Den of Evil: clear every monster inside, then speak to Akara for a skill point.","A useful early place to gain experience and find basic equipment. Use the remaining-monsters counter to find stragglers."),
  new GuideRegion(1,"Cold Plains & Burial Grounds","The Cold Plains waypoint leads toward the Burial Grounds and its crypts.","Sisters' Burial Grounds: defeat Blood Raven and return to Kashya for a Rogue mercenary.","Visit the Burial Grounds and nearby crypts for monsters and early gear; choose a difficulty your build can clear safely."),
  new GuideRegion(1,"Stony Field & Dark Wood","Find the Cairn Stones in the Stony Field and the Tree of Inifuss in the Dark Wood, through the Underground Passage.","The Search for Cain: bring the scroll to Akara, activate the stones in the indicated order, and rescue Cain in Tristram.","Tristram contains groups of monsters and unique enemies. Revisit it for early experience and items."),
  new GuideRegion(1,"Black Marsh & Forgotten Tower","Find the Forgotten Tower in the Black Marsh; the Countess is on the fifth cellar level.","The Forgotten Tower: explore the tower and defeat the Countess.","The Countess is a popular repeat target for runes. Her possible drops change with difficulty; use the Black Marsh waypoint to start a run."),
  new GuideRegion(1,"Monastery & Catacombs","Look for the Barracks, Jail, Inner Cloister and Catacombs; Andariel waits on Catacombs level 4.","Tools of the Trade: recover the Horadric Malus in the Barracks. Sisters to the Slaughter: defeat Andariel.","Andariel is a repeatable act boss for item farming. Poison resistance and antidotes help against her attacks."),
  new GuideRegion(2,"Lut Gholein Sewers","The sewers beneath Lut Gholein contain Radament on level 3.","Radament's Lair: defeat Radament and use the Book of Skill; find the Horadric Scroll nearby.","Clear the area for experience while pursuing the quest. Poison resistance can help against undead attacks."),
  new GuideRegion(2,"Halls, Maggot Lair & Viper Temple","The Halls of the Dead contain the Horadric Cube; the Maggot Lair holds the staff, and the Claw Viper Temple holds the amulet.","The Horadric Staff and Tainted Sun: collect the pieces, transmute the staff and destroy the altar.","Keep the Cube for recipes. Narrow tunnels can be awkward for summons; reposition carefully and progress patiently."),
  new GuideRegion(2,"Arcane Sanctuary & Tombs","The Palace leads to the Arcane Sanctuary. The Summoner's journal reveals the true tomb symbol.","The Summoner and The Seven Tombs: defeat the Summoner, identify the tomb and use the completed staff to reach Duriel.","The Summoner and Duriel can be revisited. Prepare for Duriel's cold aura and close-quarters fight."),
  new GuideRegion(3,"Spider Forest & Flayer Jungle","The Spider Cavern holds Khalim's Eye; the Flayer Dungeon holds his Brain. The Gidbinn is in the Flayer Jungle.","Khalim's Will: collect the relics. Blade of the Old Religion: recover the Gidbinn and return it to Ormus.","Dense groups can reward area damage, but small fast enemies can overwhelm fragile characters."),
  new GuideRegion(3,"Kurast Bazaar & Sewers","The Ruined Temple contains Lam Esen's Tome; Khalim's Heart is in the Kurast Sewers.","Lam Esen's Tome: return the book to Alkor for attribute points. Collect the Heart for Khalim's Will.","Explore the temples and sewers for monsters and chests. Pack space and a town portal make longer runs easier."),
  new GuideRegion(3,"Travincal & Durance of Hate","The High Council guards Travincal. After opening the way, the Durance leads to Mephisto on level 3.","The Blackened Temple: defeat the Council. Khalim's Will opens the Durance. The Guardian: defeat Mephisto.","The Council and Mephisto are popular repeat targets for loot. Bring fire resistance for the Council and watch for dangerous Durance monsters."),
  new GuideRegion(4,"Plains of Despair","Search the Plains of Despair for Izual.","The Fallen Angel: defeat Izual and speak to Tyrael for two skill points.","The open area has many monsters, but its layout and enemy groups vary. Finish the reward on each difficulty."),
  new GuideRegion(4,"River of Flame & Hellforge","The Hellforge and Hephasto are in the River of Flame; the river also leads toward the Chaos Sanctuary.","The Hellforge: use the Hellforge Hammer to destroy Mephisto's Soulstone.","The Hellforge quest awards gems and a rune in the expansion; the rune range depends on difficulty. This is a quest reward, not a repeatable drop per character and difficulty."),
  new GuideRegion(4,"Chaos Sanctuary","Five seals surround Diablo's sanctuary. Opening them releases dangerous seal guardians.","Terror's End: open the seals and defeat Diablo.","A popular late-game run for experience and items. Expect mixed damage types and immunities on higher difficulties."),
  new GuideRegion(5,"Bloody Foothills & Frigid Highlands","Shenk the Overseer is in the Bloody Foothills; imprisoned soldiers are in the Frigid Highlands.","Siege on Harrogath: defeat Shenk and return to Larzuk. Rescue on Mount Arreat: free the soldiers for Qual-Kehk.","Shenk and nearby Eldritch are commonly visited from the Frigid Highlands waypoint for quick monster kills."),
  new GuideRegion(5,"Frozen River & Halls of Vaught","Anya is trapped in the Frozen River. Nihlathak is in the Halls of Vaught, reached through Anya's portal after her rescue.","Prison of Ice: rescue Anya. Betrayal of Harrogath: defeat Nihlathak.","Nihlathak is a repeat target for keys in Hell difficulty. His corpse explosions can be deadly; keep distance and control corpses where possible."),
  new GuideRegion(5,"Arreat Summit & Worldstone Keep","The Ancients guard Arreat Summit; the Worldstone Keep leads to the Throne of Destruction and Baal.","Rite of Passage: defeat the Ancients. Eve of Destruction: defeat Baal. Ancients require level 20/40/60 in Normal/Nightmare/Hell for quest credit.","Baal and his waves are common experience and item targets. Prepare for varied monsters and resistances."),
  new GuideRegion(1,"Tamoe Highland & The Pit","The Pit is a two-level optional dungeon in the Tamoe Highland, reachable from the Outer Cloister side of the monastery.","No main quest requires The Pit. Save the Outer Cloister waypoint for repeat trips.","A popular Hell item-farming area with many boss packs. Archers and mixed immunities can be dangerous; bring a second damage source or rely on your demon where appropriate."),
  new GuideRegion(1,"Secret Cow Level","After completing the final act quest on the current difficulty, collect Wirt's Leg in Tristram and transmute it with a Tome of Town Portal in the Rogue Encampment.","The portal leads to an optional area; it is separate from the main quest line. Use ingredients obtained for the current difficulty.","Dense packs make the area a popular target for experience, socketable bases and runes. Keep a retreat route and avoid surrounding your character."),
  new GuideRegion(2,"Rocky Waste & Stony Tomb","Find the Stony Tomb in the Rocky Waste outside Lut Gholein. It has two levels and no waypoint.","Optional side dungeon; it is not needed for the Horadric Staff.","Both Stony Tomb levels became area level 85 on Hell in patch 2.4. A useful alternative to repeatedly farming act bosses, provided your build can clear its monsters safely."),
  new GuideRegion(2,"Lost City & Ancient Tunnels","The Ancient Tunnels entrance is in the Lost City; use the Lost City waypoint and look for a trapdoor.","Optional side dungeon. The Lost City also connects toward the Valley of Snakes for the Tainted Sun quest.","A well-known Hell farming area for monster packs and chests. Check resistances on individual bosses rather than assuming every monster can be damaged by your main element."),
  new GuideRegion(3,"Golden Bird & Kurast Docks","The Jade Figurine can be found from a unique monster in Act III. Bring it to Meshif, then follow the town conversations to Alkor.","The Golden Bird: trade the figurine for the Golden Bird, then receive and use Alkor's Potion of Life for a permanent life reward.","Complete this while progressing through the jungle; there is no need to stop for a dedicated farming run. The reward can be earned again on each difficulty."),
  new GuideRegion(3,"Lower Kurast","Use the Lower Kurast waypoint to reach its buildings, containers and surrounding monsters.","There is no major quest objective in Lower Kurast itself. It lies on the route toward the Kurast Bazaar.","Players often check the chests and other containers in the huts. Results are random and affected by game conditions; clear or avoid enemies according to your build."),
  new GuideRegion(5,"Nihlathak's Temple & Pindleskin","After rescuing Anya, her red portal leads to Nihlathak's Temple. Pindleskin and his pack guard the entrance to the Halls.","The temple is on the route for Betrayal of Harrogath. Pindleskin is an optional target.","A short run while the red portal is available. His pack can charge suddenly, so summon your demon and prepare defenses before entering."),
  new GuideRegion(1,"Act I: Safer experience & item route","Start from the Cold Plains waypoint. Clear the Burial Grounds and one open route toward the Stony Field; add the Forgotten Tower from the Black Marsh waypoint only when your character is comfortable there.","Blood Raven is part of Sisters' Burial Grounds. The Tower is optional, so it can be skipped without slowing campaign progress.","BEST FOR: early experience, basic upgrades and a low-pressure return route. The Cold Plains is open enough to retreat, regroup your summons and avoid being surrounded. Use the Burial Grounds when you want more monsters, then leave once rare packs begin taking too long. For early runes, make the Countess an optional final stop rather than forcing the narrow Tower on every run. If archer, ghost or cursed packs begin to consume potions, reset the game or stay in the open fields instead of pressing through the stairs."),
  new GuideRegion(2,"Act II: Safer experience & item route","Use the Rocky Waste exit outside Lut Gholein to find the Stony Tomb. Its two levels are a self-contained optional route; return to town through a portal rather than walking back through the desert.","The Stony Tomb is optional and does not block the Horadric Staff quest, so it is easy to leave for later if the monster mix is uncomfortable.","BEST FOR: a focused dungeon clear with items and experience, especially once it can be completed without repeated retreats. It has more room to position a mercenary and your demon than the Maggot Lair, making it a friendlier choice for minion builds. Clear the entrance pack first, work outward from doorways, and skip dangerous unique packs instead of trying to prove the run. In Hell, Ancient Tunnels from the Lost City waypoint is a stronger item route once your resistances and damage are ready; it is not a requirement for a safe progression loop."),
  new GuideRegion(3,"Act III: Safer experience & item route","For combat experience, start at the Flayer Jungle waypoint and clear a short exterior loop before returning. For a lower-combat item run, use the Lower Kurast waypoint and check nearby huts, chests and weapon or armor racks.","Neither route requires a dedicated quest turn-in. Keep the Gidbinn and Khalim relic objectives separate from a farming run when you want a quick reset.","BEST FOR: choose Flayer Jungle for experience and Lower Kurast for quick item checks. Do not try to full-clear every jungle branch: fast small enemies and dense packs can turn a safe run into a potion drain. In Lower Kurast, take the containers close to the waypoint, town out when inventory fills, and leave hostile packs behind if the goal is loot rather than experience. These routes are safer when they remain short; a fast reset after a clean loop is better than forcing a bad map or a dangerous champion pack."),
  new GuideRegion(4,"Act IV: Safer experience & item route","Use the City of the Damned or River of Flame waypoint for a small, deliberate exterior loop. Add Izual or the Hellforge only when the relevant quest is still open; save the Chaos Sanctuary for a separate, prepared run.","Izual grants skill points and the Hellforge is a one-time quest reward. Chaos Sanctuary finishes the act through Terror's End.","BEST FOR: controlled experience while progressing, rather than a truly low-risk farm. Act IV has fewer forgiving detours and its enemy damage can jump sharply, so treat open terrain as your safety tool: pull one group at a time, keep a town portal behind you, and do not chase monsters into corners. River of Flame and Chaos Sanctuary can be excellent item and experience content once your build handles their immunities and damage, but they are not the safer choice for an undergeared character. A clean short loop in the Plains of Despair or River is the better stopgap until your gear improves."),
  new GuideRegion(5,"Act V: Safer experience & item route","Take the Frigid Highlands waypoint, defeat Eldritch near the waypoint, then travel toward Shenk in the Bloody Foothills if the first fight is comfortable. After rescuing Anya, Pindleskin is an optional short stop through her red portal.","Eldritch is an optional target. Shenk completes Siege on Harrogath; rescuing Anya unlocks her portal and continues Prison of Ice.","BEST FOR: quick elite kills, experience and item chances with a short retreat path. Let your mercenary and demon engage first, especially when Eldritch's pack spawns with dangerous modifiers. Shenk is worth adding only when the Foothills approach remains quick; skip him when ranged attackers, exploding siege effects or a bad elite pack slow the route. Pindleskin is fast but begins at close range, so raise defenses and summon before entering. Worldstone Keep and Baal offer more experience later, but their varied monster groups make them a higher-risk route until your character is ready."),
  new GuideRegion(5,"Terror Zones","Once Terror Zones are enabled for your game, the active region is announced in game and marked on the waypoint menu.","Terror Zones are an optional endgame activity; availability depends on your difficulty and game progress.","A terrorized area's monster levels can increase with the player level, subject to difficulty caps. Check the current zone in game and choose one your build can clear safely; the guide does not predict the live rotation.")
 };
}
